import{_ as i,o as d,a as o,b as t}from"./app.DKoEZOcr.js";const s=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"调用","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/invocation/single_operator_api_call"},{"text":"基于simplified key的运行时选择流程","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/invocation/simplified_key_runtime_flow"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/invocation/simplified_key_runtime_flow.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/invocation/simplified_key_runtime_flow.md","outlineHeaders":[{"level":2,"title":"运行时流程","slug":"运行时流程","link":"#运行时流程"},{"level":2,"title":"AddCustomTemplate示例","slug":"AddCustomTemplate示例","link":"#AddCustomTemplate示例"},{"level":2,"title":"开发者需要保证的对应关系","slug":"开发者需要保证的对应关系","link":"#开发者需要保证的对应关系"},{"level":2,"title":"失败处理","slug":"失败处理","link":"#失败处理"},{"level":2,"title":"与两段式调用的关系","slug":"与两段式调用的关系","link":"#与两段式调用的关系"},{"level":2,"title":"相关文档","slug":"相关文档","link":"#相关文档"}],"lastUpdated":1787886219000}'),n={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/invocation/simplified_key_runtime_flow.md"};function a(l,e,c,r,p,m){return d(),o("div",null,[...e[0]||(e[0]=[t('<div><article class="markdown-body"><h1>基于simplified key的运行时选择流程</h1><p>本文介绍配置<code>GenSimplifiedKey</code>后的运行时流程。该机制用于从同一算子的多份预编译核函数（Kernel）binary中选择与本次调用条件匹配的一份。算子开发者负责提供回调和编译配置JSON；运行时框架负责调用回调、组装完整simplified key、查找并选择binary。</p><p>回调的实现见<a href="../design_and_implementation/gen_simplified_key.html">GenSimplifiedKey回调实现</a>，JSON的提供和编译产物见<a href="../compilation_and_deployment/simplified_key_json_configuration.html">simplified key二进制配置JSON</a>。</p><h2 id="运行时流程">运行时流程<a class="header-anchor" href="#运行时流程">​</a></h2><p>在<code>aclnnXxxGetWorkspaceSize</code>阶段，运行时按以下顺序处理：</p><ol><li>加载算子包中的Host侧算子实现和<code>binary_info_config.json</code>，取得该OpType的<code>binaryList</code>及<code>GenSimplifiedKey</code>回调。</li><li>根据本次调用的输入、输出、属性和目标AI处理器创建或复用<code>TilingContext</code>。</li><li>调用算子注册的<code>GenSimplifiedKey</code>回调。回调读取<code>TilingContext</code>并写出自定义simplified key片段，例如<code>custom_fp16</code>。</li><li>运行时框架补齐算子类型、确定性和实现模式等公共维度，生成完整simplified key，例如<code>AddCustomTemplate/d=0,p=1/custom_fp16</code>。</li><li>运行时使用完整Key在<code>binary_info_config.json</code>的<code>binaryList</code>中查找，得到匹配的<code>.o</code>和配套<code>.json</code>路径，并加载对应binary。</li><li>运行时调用已注册的<code>TilingFunc</code>，计算TilingData、workspace、BlockDim和TilingKey；随后创建executor并返回给调用方。</li><li>在<code>aclnnXxx</code>执行阶段，运行时使用已选择的binary和前一阶段准备的Tiling结果下发核函数（Kernel）。</li></ol><p>simplified key选择发生在Tiling之前的binary匹配阶段。<code>GenSimplifiedKey</code>不替代<code>TilingFunc</code>：前者用于选择哪份预编译binary，后者用于计算该binary本次执行需要的运行参数。</p><h2 id="AddCustomTemplate示例">AddCustomTemplate示例<a class="header-anchor" href="#AddCustomTemplate示例">​</a></h2><p><code>AddCustomTemplate</code>预编译了FP16和FP32两份binary。其回调根据输入<code>x</code>的dtype生成片段，运行时完成后续选择：</p><p><strong>表1</strong> AddCustomTemplate运行时选择示例</p><table><thead><tr><th>本次调用</th><th>回调结果</th><th>运行时完整Key示例</th><th>选中的binary</th></tr></thead><tbody><tr><td><code>x</code>为FP16，<code>y</code>和<code>z</code>为FP16</td><td><code>custom_fp16</code></td><td><code>AddCustomTemplate/d=0,p=1/custom_fp16</code></td><td><code>AddCustomTemplate_FP16.o</code></td></tr><tr><td><code>x</code>为FP32，<code>y</code>和<code>z</code>为FP32</td><td><code>custom_fp32</code></td><td><code>AddCustomTemplate/d=0,p=1/custom_fp32</code></td><td><code>AddCustomTemplate_FP32.o</code></td></tr></tbody></table><p>这里的<code>d=...</code>和<code>p=...</code>由运行时按调用公共条件处理；算子开发者只维护最后的<code>custom_fp16</code>或<code>custom_fp32</code>片段。实际配置中同一份binary可以对应多个完整Key，以覆盖不同的确定性或实现模式组合。</p><h2 id="开发者需要保证的对应关系">开发者需要保证的对应关系<a class="header-anchor" href="#开发者需要保证的对应关系">​</a></h2><p>运行时能够选择正确binary的前提是两端使用同一套规则：</p><p><strong>表2</strong> 编译侧与运行时回调侧的对应关系</p><table><thead><tr><th>编译侧</th><th>运行时回调侧</th></tr></thead><tbody><tr><td>JSON为每个支持组合声明唯一的<code>bin_filename</code>和<code>simplified_key</code>。</td><td><code>GenSimplifiedKey</code>对相同调用组合生成相同的<code>simplified_key</code>。</td></tr><tr><td>输入输出dtype、format、shape和属性组合与原型、核函数（Kernel）实现一致。</td><td>读取所有会影响binary选择的输入、输出、shape和属性，不遗漏组合维度。</td></tr><tr><td>编译产物将完整Key、<code>.o</code>路径和<code>.json</code>路径写入<code>binary_info_config.json</code>。</td><td>不拼接完整Key前缀，不加载文件，不选择binary。</td></tr></tbody></table><p>例如，如果binary由两个输入的dtype共同决定，回调必须同时读取两个输入；只根据第一个输入生成Key会使不同组合落入同一个片段，导致查找错误或找不到binary。</p><h2 id="失败处理">失败处理<a class="header-anchor" href="#失败处理">​</a></h2><p>以下情况会导致本次调用无法通过自定义simplified key匹配到预编译binary：</p><ul><li>未注册<code>GenSimplifiedKey</code>回调，或回调为空。</li><li>回调返回失败，例如输入描述为空或遇到未支持的dtype。</li><li>回调生成的片段为空、超长或与JSON中的<code>simplified_key</code>不一致。</li><li>JSON未编译出该调用组合，或部署时缺少对应的<code>.o</code>、<code>.json</code>和<code>binary_info_config.json</code>。</li></ul><p>因此，新增一种binary组合时必须同步完成三项工作：新增JSON项、更新回调分支、重新编译并部署算子包。只改其中一端都会破坏编译产物与运行时选择规则的一致性。</p><h2 id="与两段式调用的关系">与两段式调用的关系<a class="header-anchor" href="#与两段式调用的关系">​</a></h2><p>simplified key选择属于<code>aclnnXxxGetWorkspaceSize</code>阶段的准备工作。参数缓存命中时，运行时可以复用已保存的binary和Tiling信息；缓存未命中时，才执行上述回调、查找和Tiling流程。<code>aclnnXxx</code>执行阶段不重新生成Key，而是使用executor中已准备好的binary和Tiling结果。</p><h2 id="相关文档">相关文档<a class="header-anchor" href="#相关文档">​</a></h2><ul><li><a href="./runtime_loading_mechanism.html">运行时加载机制</a>：了解单算子两段式调用、缓存和通用binary匹配行为。</li><li><a href="../design_and_implementation/gen_simplified_key.html">GenSimplifiedKey回调实现</a>：了解回调签名、注册方法和编写要求。</li><li><a href="../compilation_and_deployment/simplified_key_json_configuration.html">simplified key二进制配置JSON</a>：了解完整Key和binary路径如何写入编译产物。</li></ul></article></div>',1)])])}const g=i(n,[["render",a]]);export{s as __pageData,g as default};
